with filtered_payments as (select *, to_date(paid_at) as paid_at_date from payments where status = 'SUCCESS' and paid_at < '2024-02-09'), summary as (select quarter(paid_at_date) as paid_quarter, method, sum(case when method = 'promptpay' then 1 else 0 end) as promptpay_count, max(amount) - min(amount) as amount_range from filtered_payments group by quarter(paid_at_date), method) select * from summary where promptpay_count > 34 order by method desc, paid_quarter limit 1
